select paid_cohort, status, min_amount from (select case when year(paid_at) < 2024 then 'before_2024' when year(paid_at) = 2024 then '2024' else 'after_2024' end paid_cohort, status, min(amount) min_amount from payments where order_id is not null group by case when year(paid_at) < 2024 then 'before_2024' when year(paid_at) = 2024 then '2024' else 'after_2024' end, status) agg where min_amount < 860;
